hints:
```
for each row i:
    find maximal runs of non-'#' cells
    for each run [start, end) with length == word.length():
        if cells match word forward  -> return true
        if cells match word reversed -> return true
for each column j:
    same as above on column cells
return false
```

code.cpp:
class Solution {
public:
    bool placeWordInCrossword(vector<vector<char>>& board, string word) {
        int m = board.size();
        int n = board[0].size();
        int wl = (int)word.size();

        // Horizontal runs
        for (int i = 0; i < m; i++) {
            int j = 0;
            while (j < n) {
                if (board[i][j] == '#') { j++; continue; }
                int start = j;
                while (j < n && board[i][j] != '#') j++;
                int len = j - start;
                if (len == wl) {
                    bool fwd = true;
                    for (int k = 0; k < wl && fwd; k++) {
                        char c = board[i][start + k];
                        if (c != ' ' && c != word[k]) fwd = false;
                    }
                    if (fwd) return true;
                    bool rev = true;
                    for (int k = 0; k < wl && rev; k++) {
                        char c = board[i][start + k];
                        if (c != ' ' && c != word[wl - 1 - k]) rev = false;
                    }
                    if (rev) return true;
                }
            }
        }

        // Vertical runs
        for (int j = 0; j < n; j++) {
            int i = 0;
            while (i < m) {
                if (board[i][j] == '#') { i++; continue; }
                int start = i;
                while (i < m && board[i][j] != '#') i++;
                int len = i - start;
                if (len == wl) {
                    bool fwd = true;
                    for (int k = 0; k < wl && fwd; k++) {
                        char c = board[start + k][j];
                        if (c != ' ' && c != word[k]) fwd = false;
                    }
                    if (fwd) return true;
                    bool rev = true;
                    for (int k = 0; k < wl && rev; k++) {
                        char c = board[start + k][j];
                        if (c != ' ' && c != word[wl - 1 - k]) rev = false;
                    }
                    if (rev) return true;
                }
            }
        }

        return false;
    }
};
